import json
from pathlib import Path

p = Path("_xmind_tk_dash_new/content.json")
data = json.loads(p.read_text(encoding="utf-8"))

def walk(node, depth=0, lines=None):
    if lines is None:
        lines = []
    title = node.get("title") or node.get("text") or ""
    if isinstance(title, dict):
        title = title.get("content") or str(title)
    title = str(title).replace("\n", " | ").strip()
    if title:
        lines.append("  " * depth + "- " + title)
    # notes
    notes = node.get("notes")
    if notes:
        plain = notes.get("plain", {}) if isinstance(notes, dict) else {}
        content = plain.get("content") if isinstance(plain, dict) else None
        if content:
            for ln in str(content).splitlines():
                lines.append("  " * depth + "  · " + ln.strip())
    kids = node.get("children") or {}
    attached = []
    if isinstance(kids, dict):
        attached = kids.get("attached") or kids.get("detached") or []
        if not attached and "topics" in kids:
            attached = kids["topics"]
    elif isinstance(kids, list):
        attached = kids
    for c in attached or []:
        walk(c, depth + 1, lines)
    return lines

# XMind Zen structure: list of sheets
if isinstance(data, list):
    sheets = data
elif isinstance(data, dict) and "rootTopic" in data:
    sheets = [data]
else:
    sheets = data if isinstance(data, list) else [data]

all_lines = []
for i, sheet in enumerate(sheets):
    name = sheet.get("title") or sheet.get("name") or f"sheet{i}"
    all_lines.append(f"# {name}")
    root = sheet.get("rootTopic") or sheet.get("root") or sheet
    all_lines.extend(walk(root, 0))
    all_lines.append("")

text = "\n".join(all_lines)
Path("_xmind_tk_dash_new/outline.md").write_text(text, encoding="utf-8")
print(text)
