# Also list all top-level windows with ziniao-ish titles
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
using System.Collections.Generic;
public class WinEnum {
  public delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  public static List<string> List() {
    var r = new List<string>();
    EnumWindows((h, l) => {
      if (!IsWindowVisible(h)) return true;
      var sb = new StringBuilder(512);
      GetWindowText(h, sb, 512);
      var t = sb.ToString();
      if (!string.IsNullOrWhiteSpace(t)) r.Add(h.ToInt64() + "\t" + t);
      return true;
    }, IntPtr.Zero);
    return r;
  }
}
"@
[WinEnum]::List() | Where-Object { $_ -match '紫鸟|ziniao|Ziniao|Browser|登录' } | ForEach-Object { Write-Host $_ }

Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms

$hwnd = [IntPtr]132874
[WinEnum]::ShowWindow($hwnd, 9) | Out-Null  # restore
Start-Sleep -Milliseconds 300
[WinEnum]::SetForegroundWindow($hwnd) | Out-Null
Start-Sleep -Milliseconds 400

$root = [System.Windows.Automation.AutomationElement]::FromHandle($hwnd)
if (-not $root) { throw "no automation element" }

function Dump-Tree($el, $depth, $maxDepth) {
  if ($depth -gt $maxDepth) { return }
  $name = $el.Current.Name
  $ctrl = $el.Current.ControlType.ProgrammaticName
  $auto = $el.Current.AutomationId
  $cls = $el.Current.ClassName
  if ($name -or $ctrl -match 'Button|Edit|Combo|Text') {
    $pad = '  ' * $depth
    Write-Host ("{0}[{1}] name='{2}' id='{3}' class='{4}'" -f $pad, $ctrl, $name, $auto, $cls)
  }
  $cond = [System.Windows.Automation.Condition]::TrueCondition
  $children = $el.FindAll([System.Windows.Automation.TreeScope]::Children, $cond)
  foreach ($c in $children) { Dump-Tree $c ($depth+1) $maxDepth }
}

Write-Host "=== UI tree (depth 6) ==="
Dump-Tree $root 0 6

# Find button named 登录
$btnCond = New-Object System.Windows.Automation.AndCondition(
  (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Button)),
  (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::NameProperty, '登录'))
)
$btn = $root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $btnCond)
if ($btn) {
  Write-Host "FOUND login button"
  try {
    $inv = $btn.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
    $inv.Invoke()
    Write-Host "Invoke() called"
  } catch {
    Write-Host "Invoke failed: $_ — try click center"
    $rect = $btn.Current.BoundingRectangle
    $x = [int]($rect.X + $rect.Width/2)
    $y = [int]($rect.Y + $rect.Height/2)
    Write-Host "click $x,$y"
    [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point($x, $y)
    Start-Sleep -Milliseconds 200
    Add-Type @"
using System;
using System.Runtime.InteropServices;
public class Mouse {
  [DllImport("user32.dll")] public static extern void mouse_event(int dwFlags, int dx, int dy, int cButtons, int dwExtraInfo);
  public const int LEFTDOWN = 0x02;
  public const int LEFTUP = 0x04;
  public static void Click() { mouse_event(LEFTDOWN, 0, 0, 0, 0); mouse_event(LEFTUP, 0, 0, 0, 0); }
}
"@
    [Mouse]::Click()
    Write-Host "mouse click done"
  }
} else {
  Write-Host "login button NOT found by name; listing all buttons:"
  $allBtn = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Button)
  $btns = $root.FindAll([System.Windows.Automation.TreeScope]::Descendants, $allBtn)
  foreach ($b in $btns) {
    Write-Host ("BTN name='{0}' id='{1}' rect={2}" -f $b.Current.Name, $b.Current.AutomationId, $b.Current.BoundingRectangle)
  }
}

Add-Type @"
using System;
using System.Runtime.InteropServices;
public class Native {
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern void mouse_event(int dwFlags, int dx, int dy, int cButtons, int dwExtraInfo);
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
  [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern bool ClientToScreen(IntPtr hWnd, ref POINT lpPoint);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  [StructLayout(LayoutKind.Sequential)] public struct POINT { public int X, Y; }
  public const int LEFTDOWN = 0x02;
  public const int LEFTUP = 0x04;
  public static void Click(int x, int y) {
    SetCursorPos(x, y);
    System.Threading.Thread.Sleep(80);
    mouse_event(LEFTDOWN, 0, 0, 0, 0);
    System.Threading.Thread.Sleep(40);
    mouse_event(LEFTUP, 0, 0, 0, 0);
  }
}
"@

$hwnd = [IntPtr]132874
[Native]::ShowWindow($hwnd, 9) | Out-Null
Start-Sleep -Milliseconds 200
[Native]::SetForegroundWindow($hwnd) | Out-Null
Start-Sleep -Milliseconds 300

$wr = New-Object Native+RECT
[Native]::GetWindowRect($hwnd, [ref]$wr) | Out-Null
Write-Host ("window L={0} T={1} R={2} B={3} W={4} H={5}" -f $wr.Left, $wr.Top, $wr.Right, $wr.Bottom, ($wr.Right-$wr.Left), ($wr.Bottom-$wr.Top))

# Login form is left panel; blue 登录 button is centered horizontally in form, near bottom of form card.
# From screenshot: form is roughly left half of window, button is wide blue bar above bottom padding.
$w = $wr.Right - $wr.Left
$h = $wr.Bottom - $wr.Top
# Typical Ziniao login: content card ~420px wide centered in left column; button ~ mid of left panel
# Try several Y positions around lower third of window, X at ~ center of left 45% panel
$candidates = @(
  @{x=[int]($wr.Left + $w * 0.28); y=[int]($wr.Top + $h * 0.78)},
  @{x=[int]($wr.Left + $w * 0.30); y=[int]($wr.Top + $h * 0.72)},
  @{x=[int]($wr.Left + $w * 0.32); y=[int]($wr.Top + $h * 0.75)},
  @{x=[int]($wr.Left + $w * 0.25); y=[int]($wr.Top + $h * 0.80)},
  @{x=[int]($wr.Left + $w * 0.35); y=[int]($wr.Top + $h * 0.70)}
)

# First bring to front and screenshot-less: press Enter (often submits login when password focused)
Add-Type -AssemblyName System.Windows.Forms
# Click password field area then Enter as safer first attempt
$pwdX = [int]($wr.Left + $w * 0.30)
$pwdY = [int]($wr.Top + $h * 0.58)
Write-Host "click password area $pwdX,$pwdY then Enter"
[Native]::Click($pwdX, $pwdY)
Start-Sleep -Milliseconds 300
[System.Windows.Forms.SendKeys]::SendWait("{ENTER}")
Start-Sleep -Seconds 2

# Also click the blue login button candidate
$bx = [int]($wr.Left + $w * 0.30)
$by = [int]($wr.Top + $h * 0.76)
Write-Host "click login button candidate $bx,$by"
[Native]::Click($bx, $by)
Start-Sleep -Seconds 3

# Check login status via doctor
ziniao-cli doctor 2>&1 | Select-Object -Last 25
Write-Host "===="
# window title change?
Get-Process | Where-Object { $_.ProcessName -match 'ziniao' -and $_.MainWindowHandle -ne 0 } | ForEach-Object {
  Write-Host ("pid={0} title={1}" -f $_.Id, $_.MainWindowTitle)
}

Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Runtime.InteropServices;
using System.Drawing;
using System.Drawing.Imaging;
public class Cap {
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr hWnd, IntPtr hdcBlt, int nFlags);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  public static void Shot(IntPtr hwnd, string path) {
    ShowWindow(hwnd, 9);
    SetForegroundWindow(hwnd);
    System.Threading.Thread.Sleep(300);
    RECT r; GetWindowRect(hwnd, out r);
    int w = r.Right - r.Left, h = r.Bottom - r.Top;
    using (var bmp = new Bitmap(w, h, PixelFormat.Format32bppArgb)) {
      using (var g = Graphics.FromImage(bmp)) {
        IntPtr hdc = g.GetHdc();
        // PW_RENDERFULLCONTENT = 2
        bool ok = PrintWindow(hwnd, hdc, 2);
        g.ReleaseHdc(hdc);
        if (!ok) {
          g.CopyFromScreen(r.Left, r.Top, 0, 0, new Size(w, h), CopyPixelOperation.SourceCopy);
        }
      }
      bmp.Save(path, ImageFormat.Png);
    }
  }
}
"@
