12	    if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
13	    if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
14	    if (/\$|USD|美金|美元/i.test(s)) return 'USD';
