26	      .replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '')
27	      .replace(/%/g, '');
28	    const paren = s.match(/^\((.+)\)$/);
29	    if (paren) s = `-${paren[1]}`;
30	    const n = Number(s);
31	    return Number.isFinite(n) ? n : null;
