41	      raw.match(/日预算\s*[:：]?\s*([0-9]+(?:[.,][0-9]+)?)/i) ||
42	      raw.match(/([0-9]+(?:[.,][0-9]+)?)\s*(?:USD|GBP|EUR|CNY|美金|美元)?/i);
43	    if (m) return parseNumber(m[1]);
