47	  const HEADER_ALIASES = {
48	    planStatus: ['开/关', '开关', '投放开关', 'enable', 'enabled', 'switch', 'on/off', 'toggle'],
49	    // P1: 比 spend/roi 更具体的列优先匹配
50	    targetRoi: ['目标 roi', '目标roi', '目标 roas', '目标roas', 'target roi', 'target roas'],
51	    avgOrderCost: [
52	      '平均下单成本',
53	      '平均下单',
54	      'cost per order',
55	      'cost per purchase',
56	      'avg order cost',
57	      'cpa'
58	    ],
59	    netCost: ['净成本', 'net cost', 'net spend'],
60	    // 勿用裸「预算」：会误吃「创意作品加热预算」列，把日预算盖成 null
61	    dailyBudget: ['当前预算', '日预算', 'daily budget', 'current budget'],
62	    deliveryStatus: ['状态', '投放状态', '计划状态', 'status', 'delivery status'],
63	    campaign: [
64	      '品名',
65	      '广告计划名称',
66	      '广告系列',
