72	      '名称'
73	    ],
74	    spend: ['广告花费', '广告成本', '花费', '成本', '消耗', 'cost', 'spend', 'ad spend'],
75	    orders: [
76	      '销量',
77	      '订单',
78	      'sku 订单',
79	      'sku订单',
80	      'sku 订单数',
81	      'sku订单数',
82	      'orders',
83	      'units',
84	      'units sold'
85	    ],
86	    roi: ['roi', 'roas', '投资回报率', '投资回报', '回报率'],
87	    revenue: ['销售额', '总收入', '销售收入', '收入', 'gmv', 'revenue', 'gross revenue']
88	  };
89	
90	  const MONEY_FIELDS = {
91	    spend: 1,
92	    revenue: 1,
93	    dailyBudget: 1,
94	    netCost: 1,
95	    avgOrderCost: 1
96	  };
97	  const NUM_FIELDS = {
98	    spend: 1,
99	    revenue: 1,
100	    orders: 1,
101	    roi: 1,
102	    dailyBudget: 1,
103	    targetRoi: 1,
104	    netCost: 1,
105	    avgOrderCost: 1
106	  };
107	  const TEXT_FIELDS = { campaign: 1, deliveryStatus: 1 };
108	
109	  function matchHeaderField(headerText) {
110	    const t = cleanText(headerText).toLowerCase();
111	    if (!t) return null;
112	    // 具体列优先，避免「成本」吃掉「净成本/平均下单成本」，「ROI」吃掉「目标 ROI」
113	    const order = [
114	      'planStatus',
115	      'targetRoi',
116	      'avgOrderCost',
117	      'netCost',
118	      'dailyBudget',
119	      'deliveryStatus',
120	      'roi',
121	      'spend',
122	      'orders',
123	      'revenue',
124	      'campaign'
125	    ];
126	    for (const field of order) {
