130	        const hit =
131	          t === al ||
132	          t.includes(al) ||
133	          (al.length >= 4 && t.length >= 4 && al.includes(t));
134	        if (!hit) continue;
135	        if (field === 'spend') {
136	          if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|净成本|net cost|预算|budget/.test(t)) {
137	            continue;
138	          }
139	        }
140	        if (field === 'roi') {
141	          if (/目标|保护|保障|target|protect|资格/.test(t)) continue;
142	        }
