/* TikTok ads dashboard scraper for ziniao-cli page exec. No // comments (minified to one line). */
(function () {
  function cleanText(t) {
    return String(t ?? '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function detectCurrency(text) {
    const s = String(text ?? '');
    if (/[£]|GBP|英镑/i.test(s)) return 'GBP';
    if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
    if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
    if (/\$|USD|美金|美元/i.test(s)) return 'USD';
    return null;
  }

  function parseNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    let s = String(value).trim();
    if (!s || s === '-' || s === '—') return null;
    s = s
      .replace(/[,\s]/g, '')
      .replace(/[¥$€£￥]/g, '')
      .replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '')
      .replace(/%/g, '');
    const paren = s.match(/^\((.+)\)$/);
    if (paren) s = `-${paren[1]}`;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }

  /** 当前预算单元格常见：「10.00 USD 日预算：10.00 USD」→ 取日预算优先 */
  function parseBudgetNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    const raw = String(value).trim();
    if (!raw || raw === '-' || raw === '—') return null;
    const m =
      raw.match(/日预算\s*[:：]?\s*([0-9]+(?:[.,][0-9]+)?)/i) ||
      raw.match(/([0-9]+(?:[.,][0-9]+)?)\s*(?:USD|GBP|EUR|CNY|美金|美元)?/i);
    if (m) return parseNumber(m[1]);
    return parseNumber(raw);
  }

  const HEADER_ALIASES = {
    planStatus: ['开/关', '开关', '投放开关', 'enable', 'enabled', 'switch', 'on/off', 'toggle'],
    // P1: 比 spend/roi 更具体的列优先匹配
    targetRoi: ['目标 roi', '目标roi', '目标 roas', '目标roas', 'target roi', 'target roas'],
    avgOrderCost: [
      '平均下单成本',
      '平均下单',
      'cost per order',
      'cost per purchase',
      'avg order cost',
      'cpa'
    ],
    netCost: ['净成本', 'net cost', 'net spend'],
    // 勿用裸「预算」：会误吃「创意作品加热预算」列，把日预算盖成 null
    dailyBudget: ['当前预算', '日预算', 'daily budget', 'current budget'],
    deliveryStatus: ['状态', '投放状态', '计划状态', 'status', 'delivery status'],
    campaign: [
      '品名',
      '广告计划名称',
      '广告系列',
      '广告系列名称',
      '系列名称',
      'campaign',
      'campaign name',
      'product',
      '名称'
    ],
    spend: ['广告花费', '广告成本', '花费', '成本', '消耗', 'cost', 'spend', 'ad spend'],
    orders: [
      '销量',
      '订单',
      'sku 订单',
      'sku订单',
      'sku 订单数',
      'sku订单数',
      'orders',
      'units',
      'units sold'
    ],
    roi: ['roi', 'roas', '投资回报率', '投资回报', '回报率'],
    revenue: ['销售额', '总收入', '销售收入', '收入', 'gmv', 'revenue', 'gross revenue']
  };

  const MONEY_FIELDS = {
    spend: 1,
    revenue: 1,
    dailyBudget: 1,
    netCost: 1,
    avgOrderCost: 1
  };
  const NUM_FIELDS = {
    spend: 1,
    revenue: 1,
    orders: 1,
    roi: 1,
    dailyBudget: 1,
    targetRoi: 1,
    netCost: 1,
    avgOrderCost: 1
  };
  const TEXT_FIELDS = { campaign: 1, deliveryStatus: 1 };

  function matchHeaderField(headerText) {
    const t = cleanText(headerText).toLowerCase();
    if (!t) return null;
    // 具体列优先，避免「成本」吃掉「净成本/平均下单成本」，「ROI」吃掉「目标 ROI」
    const order = [
      'planStatus',
      'targetRoi',
      'avgOrderCost',
      'netCost',
      'dailyBudget',
      'deliveryStatus',
      'roi',
      'spend',
      'orders',
      'revenue',
      'campaign'
    ];
    for (const field of order) {
      for (const a of HEADER_ALIASES[field]) {
        const al = a.toLowerCase();
        // 禁止短词反包含（否则 t="roi" 会命中 al="目标 roi"）
        const hit =
          t === al ||
          t.includes(al) ||
          (al.length >= 4 && t.length >= 4 && al.includes(t));
        if (!hit) continue;
        if (field === 'spend') {
          if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|净成本|net cost|预算|budget/.test(t)) {
            continue;
          }
        }
        if (field === 'roi') {
          if (/目标|保护|保障|target|protect|资格/.test(t)) continue;
        }
        if (field === 'dailyBudget') {
          // 排除创意加热预算等；只认「当前预算 / 日预算」类表头
          if (/加热|创意|creative|boost|权益|保护/.test(t)) continue;
          if (!(t.includes('当前预算') || t.includes('日预算') || t === 'daily budget' || t === 'current budget' || t.includes('current budget') || t.includes('daily budget'))) {
            continue;
          }
        }
        if (field === 'deliveryStatus') {
          // 避免把开关列当状态；「已生效」在数据列
          if (/开关|switch|toggle|开\/关/.test(t)) continue;
          if (t === '状态' || t === 'status' || /投放状态|计划状态|delivery/.test(t)) {
            return field;
          }
          continue;
        }
        if (field === 'planStatus') {
          if (/投放状态|计划状态|delivery|operation status/.test(t) && !/开关|switch|开\/关/.test(t)) {
            // 文案型状态走 deliveryStatus
            continue;
          }
          if (t === al || t === '开关' || t === '开/关' || t === 'switch' || t === 'enable' || t === 'enabled') {
            return field;
          }
          if (/开关|switch|toggle|on\/off|开\/关/.test(t) && t.length <= 12) return field;
          continue;
        }
        if (field === 'campaign' && (al === '名称' || al === 'name')) {
          if (!/系列|campaign|广告|活动|product|品名|计划/.test(t) && t !== '名称' && t !== 'name') {
            continue;
          }
        }
        return field;
      }
    }
    return null;
  }

  function classOf(el) {
    if (!el) return '';
    return String(el.className || (el.getAttribute && el.getAttribute('class')) || '');
  }

  function readSwitchState(sw) {
    if (!sw) return null;
    const aria = sw.getAttribute && sw.getAttribute('aria-checked');
    if (aria === 'true') return 'on';
    if (aria === 'false') return 'off';
    if (sw.tagName === 'INPUT') {
      if (sw.type === 'checkbox' || sw.getAttribute('role') === 'switch') {
        return sw.checked ? 'on' : 'off';
      }
    }
    const cls =
      classOf(sw) +
      ' ' +
      classOf(sw.parentElement) +
      ' ' +
      classOf(sw.parentElement && sw.parentElement.parentElement);

