    return String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
  }
  function pushUnique(arr, seen, obj) {
    var key = (obj.href || '') + '|' + (obj.text || '');
    if (seen[key]) return;
    seen[key] = 1;
    arr.push(obj);
  }
  try {
