/* Click Compass top-nav by visible label. Ziniao page exec.
 * Return { ok, action, beforeUrl, afterUrl, matchedText, error }
 * Usage: set window.__QQ_CLICK_NAV_LABEL__ = '内容分析' before exec, or edit DEFAULT_LABEL.
 */
(function () {
  var DEFAULT_LABEL = '内容分析';
  function clean(t) {
    return String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
  }
  function label() {
    try {
      if (typeof window.__QQ_CLICK_NAV_LABEL__ === 'string' && window.__QQ_CLICK_NAV_LABEL__) {
        return String(window.__QQ_CLICK_NAV_LABEL__);
      }
    } catch (e) {}
    return DEFAULT_LABEL;
  }
  function clickEl(el) {
    if (!el) return false;
    try {
      el.scrollIntoView({ block: 'center', inline: 'center' });
    } catch (e1) {}
    try {
      el.dispatchEvent(new MouseEvent('mouseover', { bubbles: true, cancelable: true, view: window }));
      el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window }));
      el.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, view: window }));
      el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
      if (typeof el.click === 'function') el.click();
      return true;
    } catch (e2) {
      return false;
    }
  }
  try {
    var want = clean(label());
    var beforeUrl = location.href || '';
    var candidates = [];
    var nodes = document.querySelectorAll('div, span, a, button, li');
    for (var i = 0; i < nodes.length; i++) {
      var el = nodes[i];
      var tx = clean(el.innerText || el.textContent);
      if (!tx || tx.length > 30) continue;
      if (tx === want || tx.indexOf(want) === 0) {
        var cls = String(el.className || '');
        var score = 0;
        if (cls.indexOf('navButton') >= 0 || cls.indexOf('_navButton') >= 0) score += 5;
        if (cls.indexOf('menu') >= 0 || cls.indexOf('Menu') >= 0) score += 2;
        if (el.tagName === 'SPAN' && el.parentElement) score += 1;
        if (tx === want) score += 3;
        candidates.push({ el: el, text: tx, score: score, cls: cls.slice(0, 80) });
      }
    }
    candidates.sort(function (a, b) {
      return b.score - a.score;
    });
    if (!candidates.length) {
      return JSON.stringify({
        ok: false,
        action: 'click_nav',
        want: want,
        beforeUrl: beforeUrl,
        afterUrl: beforeUrl,
        error: 'no element with label ' + want
      });
    }
    var pick = candidates[0];
    var target = pick.el;
    // prefer clickable parent navButton
    var p = target;
    for (var d = 0; d < 4 && p; d++) {
      var pc = String(p.className || '');
      if (pc.indexOf('navButton') >= 0 || pc.indexOf('_navButton') >= 0 || pc.indexOf('cursor-pointer') >= 0) {
        target = p;
        break;
      }
      p = p.parentElement;
    }
    var clicked = clickEl(target);
    return JSON.stringify({
      ok: !!clicked,
      action: 'click_nav',
      want: want,
      matchedText: pick.text,
      matchedCls: pick.cls,
      score: pick.score,
      beforeUrl: beforeUrl,
      afterUrl: location.href || '',
      candidateCount: candidates.length,
      error: clicked ? null : 'click dispatch failed'
    });
  } catch (e) {
    return JSON.stringify({
      ok: false,
      action: 'click_nav',
      error: String(e && e.message ? e.message : e)
    });
  }
})();

/* Deep nav dump: anchors + [href] + data-* + text nodes near 数据分析/内容. */
(function () {
  function clean(t) {
    return String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
  }
  function pushUnique(arr, seen, obj) {
    var key = (obj.href || '') + '|' + (obj.text || '');
    if (seen[key]) return;
    seen[key] = 1;
    arr.push(obj);
  }
  try {
    var body = clean((document.body && (document.body.innerText || document.body.textContent)) || '');
    var seen = {};
    var links = [];

    var nodes = document.querySelectorAll('a[href], [href], [data-href], [data-path], [data-url], [data-to], [routerlink], [ng-reflect-router-link]');
    for (var i = 0; i < nodes.length; i++) {
      var el = nodes[i];
      var href =
        el.href ||
        el.getAttribute('href') ||
        el.getAttribute('data-href') ||
        el.getAttribute('data-path') ||
        el.getAttribute('data-url') ||
        el.getAttribute('data-to') ||
        el.getAttribute('routerlink') ||
        el.getAttribute('ng-reflect-router-link') ||
        '';
      var text = clean(el.innerText || el.textContent).slice(0, 120);
      if (!href && !text) continue;
      if (href && href.indexOf('javascript:') === 0) continue;
      var blob = (text + ' ' + href).toLowerCase();
      if (
        /内容|视频|商品卡|compass|analytics|data-overview|content|video|product-card|数据分析|直播/.test(blob) ||
        /compass|analytics|content|video|product/i.test(href)
      ) {
        pushUnique(links, seen, {
          text: text,
          href: href,
          tag: el.tagName,
          cls: String(el.className || '').slice(0, 80)
        });
      }
    }

    // clickable divs/spans with analytics-ish text
    var all = document.querySelectorAll('div, span, li, p, button');
    var textHits = [];
    for (var j = 0; j < all.length && textHits.length < 40; j++) {
      var n = all[j];
      if (n.children && n.children.length > 3) continue;
      var tx = clean(n.innerText || n.textContent);
      if (!tx || tx.length > 40) continue;
      if (/^(内容分析|视频和照片|视频和照片概览|商品卡|商品数据分析|数据分析|短视频|直播)$/i.test(tx) ||
          /content analytics|videos? and photos|product card/i.test(tx)) {
        textHits.push({
          text: tx,
          tag: n.tagName,
          cls: String(n.className || '').slice(0, 100),
          parentCls: n.parentElement ? String(n.parentElement.className || '').slice(0, 80) : ''
        });
      }
    }

    // script src / preload hints
    var scripts = Array.prototype.slice
      .call(document.querySelectorAll('script[src]'))
      .map(function (s) {
        return s.src;
      })
      .filter(function (s) {
        return /compass|analytics|content/i.test(s);
      })
      .slice(0, 15);

    return JSON.stringify({
      ok: true,
      module: 'content_nav_deep',
      url: location.href || '',
      title: document.title || '',
      bodyLen: body.length,
      sample: body.slice(0, 1000),
      links: links.slice(0, 50),
      textHits: textHits,
      scripts: scripts,
      error: null
    });
  } catch (e) {
    return JSON.stringify({
      ok: false,
      module: 'content_nav_deep',
      url: location.href || '',
      error: String(e && e.message ? e.message : e)
    });
  }
})();

/* Discover content-analysis nav URLs from seller center (P2.0). Ziniao page exec. */
(function () {
  function clean(t) {
    return String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
  }
  function scoreLink(text, href) {
    var t = (text + ' ' + href).toLowerCase();
    var s = 0;
    if (/content-analysis|content_analysis|\/content\//i.test(href)) s += 5;
    if (/视频和照片|video.*photo|videos?\s*and\s*photos|短视频|video-overview|video_overview|\/video/i.test(t)) s += 4;
    if (/商品卡|product-card|product_card|product-analytics|商品数据/i.test(t)) s += 4;
    if (/内容分析|content\s*analytics|content\s*analysis/i.test(t)) s += 3;
    if (/compass|数据分析|data-overview|analytics/i.test(t)) s += 1;
    if (/ads-creation|order|product\/manage|finance|health|homepage|login/i.test(href)) s -= 3;
    return s;
  }
  try {
    var body = clean((document.body && (document.body.innerText || document.body.textContent)) || '');
    var anchors = Array.prototype.slice.call(document.querySelectorAll('a[href]'));
    var seen = {};
    var links = [];
    for (var i = 0; i < anchors.length; i++) {
      var a = anchors[i];
      var href = a.href || a.getAttribute('href') || '';
      if (!href || href.indexOf('javascript:') === 0 || href === '#') continue;
      var text = clean(a.innerText || a.textContent).slice(0, 100);
      var sc = scoreLink(text, href);
      if (sc < 2) continue;
      var key = href.split('?')[0];
      if (seen[key]) continue;
      seen[key] = 1;
      links.push({ text: text, href: href, score: sc });
    }
    links.sort(function (x, y) {
      return y.score - x.score;
    });

    // also scan menu-like elements with data attributes
    var menuHints = [];
    var nodes = document.querySelectorAll('[class*="menu"], [class*="nav"], [role="menuitem"], [class*="Menu"]');
    for (var mi = 0; mi < Math.min(nodes.length, 80); mi++) {
      var nt = clean(nodes[mi].innerText).slice(0, 80);
      if (/内容|视频|商品卡|Content|Video|Product\s*card/i.test(nt)) {
        menuHints.push(nt);
      }
    }

    var tables = Array.prototype.slice.call(document.querySelectorAll('table')).slice(0, 8).map(function (tb, idx) {
      var ths = Array.prototype.slice.call(tb.querySelectorAll('thead th, tr th')).map(function (th) {
        return clean(th.innerText).slice(0, 40);
      });
      return { i: idx, headers: ths.slice(0, 15), rows: tb.querySelectorAll('tbody tr').length };
    });

    return JSON.stringify({
      ok: true,
      module: 'content_nav_discover',
      url: location.href || '',
      title: document.title || '',
      bodyLen: body.length,
      sample: body.slice(0, 800),
      hasContentWord: /内容分析|Content\s*analytics|视频和照片|商品卡/i.test(body),
      links: links.slice(0, 30),
      menuHints: menuHints.slice(0, 20),
      tables: tables,
      error: null
    });
  } catch (e) {
    return JSON.stringify({
      ok: false,
      module: 'content_nav_discover',
      url: location.href || '',
      error: String(e && e.message ? e.message : e)
    });
  }
})();

