      $item = [ordered]@{
        storeId = $sid; storeName = $sname; displayName = $display; module = $mod
        ok = $false; url = $null; error = $null; debugPath = $null
      }
      $modUrl = Get-ModuleUrl $store $cfg $mod
      $item.url = $modUrl
      Write-Step ("  -- module {0} url={1}" -f $mod, $modUrl)
