384	function ConvertTo-QingquanProductTrafficIngestItems {
385	  <#
386	    P2.1a 商品卡流量 → tiktok_product_traffic
387	    输入：scrape-product-traffic-page.js 的 payload（含 products[]）
388	    语义：窗口快照；一行一 product；biz_date 为窗口锚点日（不拆 7 日）
389	  #>
390	  param(
391	    [Parameter(Mandatory = $true)] $Payload,
392	    [Parameter(Mandatory = $true)] [string]$CollectedAt,
393	    [Parameter(Mandatory = $true)] [string]$StoreId,
394	    [Parameter(Mandatory = $true)] [string]$BizDate,
395	    [string]$StoreName = '',
396	    [string]$Currency = 'GBP',
397	    [string]$SourceUrl = ''
398	  )
399	  $items = New-Object System.Collections.ArrayList
400	  $p = $Payload
401	  if (-not $p) { Write-Output -NoEnumerate @(); return }
402	
403	  $cur = $Currency
404	  if ($p.currency) { $cur = [string]$p.currency }
405	  $src = $SourceUrl
406	  if ($p.url) { $src = [string]$p.url }
407	  $channelDefault = 'product_card'
408	  if ($p.channelDefault) { $channelDefault = [string]$p.channelDefault }
409	  elseif ($p.channel) { $channelDefault = [string]$p.channel }
410	
411	  $windowLabel = $null
412	  if ($p.window) { $windowLabel = [string]$p.window }
413	  elseif ($p.raw -and $p.raw.window) { $windowLabel = [string]$p.raw.window }
414	
415	  $pageKpis = $null
416	  if ($p.kpis) { $pageKpis = $p.kpis }
417	
418	  $rows = @()
419	  if ($p.products) { $rows = @($p.products) }
420	  elseif ($p.Rows) { $rows = @($p.Rows) }
421	
422	  foreach ($r in $rows) {
423	    $productId = ''
424	    if ($r.productId) { $productId = [string]$r.productId }
425	    elseif ($r.product_id) { $productId = [string]$r.product_id }
426	    $productName = ''
427	    if ($r.title) { $productName = [string]$r.title }
428	    elseif ($r.productName) { $productName = [string]$r.productName }
429	    elseif ($r.product_name) { $productName = [string]$r.product_name }
430	    if (-not $productId) {
431	      if ($productName -match '\b(\d{10,})\b') { $productId = $Matches[1] }
432	    }
433	    if (-not $productId) { continue }
434	
