1	/* TikTok seller center: 内容分析 → 商品卡 / 商品数据分析 (P2.0 POC).
2	 * Ziniao page exec. Card KPIs + product table (exposure/CTR/CVR).
3	 */
4	(function () {
5	  function clean(t) {
6	    return String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
7	  }
8	  function detectCurrency(text) {
9	    var s = String(text || '');
10	    if (/[£]|GBP/i.test(s)) return 'GBP';
11	    if (/[€]|EUR/i.test(s)) return 'EUR';
12	    if (/[¥￥]|CNY|RMB/i.test(s) && !/\$/.test(s)) return 'CNY';
13	    if (/\$|USD/i.test(s)) return 'USD';
14	    return null;
15	  }
16	  function parseNumber(value) {
17	    if (value == null || value === '') return null;
18	    if (typeof value === 'number' && isFinite(value)) return value;
19	    var s = String(value).trim();
20	    if (!s || s === '-' || s === '—') return null;
21	    var pct = s.match(/^(-?[\d,]+(?:\.\d+)?)\s*%$/);
22	    if (pct) {
23	      var p = Number(String(pct[1]).replace(/,/g, ''));
24	      return isFinite(p) ? p : null;
25	    }
26	    /* 24.50K / 1.2万 / 3M */
27	    var km = s.match(/-?\s*[¥$€£￥]?\s*([0-9]+(?:,[0-9]{3})*(?:\.[0-9]+)?)\s*([KkMm万亿])/);
28	    if (km) {
29	      var base = Number(String(km[1]).replace(/,/g, ''));
30	      if (isFinite(base)) {
31	        var u = km[2];
32	        if (u === 'K' || u === 'k') return base * 1000;
33	        if (u === 'M' || u === 'm') return base * 1000000;
34	        if (u === '万') return base * 10000;
35	        if (u === '亿') return base * 100000000;
36	      }
37	    }
38	    var m = s.match(/-?\s*[¥$€£￥]?\s*([0-9]+(?:,[0-9]{3})*(?:\.[0-9]+)?)/);
39	    if (m) {
40	      var n0 = Number(String(m[1]).replace(/,/g, ''));
41	      if (isFinite(n0)) return n0;
42	    }
43	    s = s.replace(/[,\s]/g, '').replace(/[¥$€£￥]/g, '').replace(/%/g, '');
44	    var n = Number(s);
45	    return isFinite(n) ? n : null;
46	  }
47	  function bodyText() {
48	    return clean((document.body && (document.body.innerText || document.body.textContent)) || '');
49	  }
50	  function findByRegex(body, patterns) {
51	    for (var i = 0; i < patterns.length; i++) {
52	      var m = body.match(patterns[i]);
53	      if (!m) continue;
54	      var raw = m[1] != null ? m[1] : m[0];
55	      var n = parseNumber(raw);
56	      if (n != null) return { value: n, label: String(m[0]).slice(0, 120) };
57	    }
58	    return null;
59	  }
60	  function cellText(el) {
61	    return clean(el && (el.innerText || el.textContent));
62	  }
63	  function matchProductHeader(h) {
64	    var t = clean(h).toLowerCase();
65	    if (!t) return null;
66	    if (/商品\s*id|product\s*id|\bid\b/.test(t) && !/视频|video/.test(t)) return 'productId';
67	    if (/商品卡\s*名称|商品|product|名称|name|title/.test(t) && !/曝光|点击|gmv|订单|ctr|cvr|转化/.test(t))
68	      return 'title';
69	    if (/曝光\s*到\s*成交|曝光.*转化|\bcvr\b|转化率|conversion\s*rate/.test(t)) return 'cvr';
70	    if (/曝光\s*用户|曝光|impression|show|展示/.test(t)) return 'impressions';
71	    if (/点击|clicks?/.test(t) && !/率|rate|ctr/.test(t)) return 'clicks';
72	    if (/\bctr\b|点击率|click-?through/.test(t)) return 'ctr';
73	    if (/订单|orders?|销量|units?|sku\s*订单/.test(t)) return 'orders';
74	    if (/\bgmv\b|销售额|成交额|revenue/.test(t)) return 'gmv';
75	    if (/渠道|channel|来源|source|流量来源/.test(t)) return 'channel';
76	    if (/日\s*客户|客户数|customers?/.test(t)) return 'customers';
77	    return null;
78	  }
79	  function scrapeProductTable() {
80	    var tables = Array.prototype.slice.call(document.querySelectorAll('table'));
81	    var best = [];
82	    var bestHeaders = [];
83	    for (var ti = 0; ti < tables.length; ti++) {
84	      var table = tables[ti];
85	      var ths = table.querySelectorAll('thead th, tr th');
86	      if (!ths.length) continue;
87	      var fields = [];
88	      var headers = [];
89	      for (var hi = 0; hi < ths.length; hi++) {
90	        var ht = cellText(ths[hi]);
91	        headers.push(ht);
92	        fields.push(matchProductHeader(ht));
93	      }
94	      var mapped = fields.filter(Boolean).length;
95	      if (mapped < 2) continue;
96	      var rows = table.querySelectorAll('tbody tr');
97	      var items = [];
98	      for (var ri = 0; ri < rows.length && items.length < 80; ri++) {
99	        var tds = rows[ri].querySelectorAll('td');
100	        if (!tds.length) continue;
101	        var row = { rawCells: [] };
102	        for (var ci = 0; ci < tds.length; ci++) {
103	          var txt = cellText(tds[ci]);
104	          row.rawCells.push(txt);
105	          var f = fields[ci];
106	          if (!f) continue;
107	          if (f === 'title' || f === 'productId' || f === 'channel') {
108	            row[f] = txt;
109	            if (f === 'title' || f === 'productId') {
110	              var a = tds[ci].querySelector('a[href]');
111	              if (a) {
112	                row.href = a.href || a.getAttribute('href') || null;
113	                if (!row.productId) {
114	                  var pm =
115	                    String(row.href || '').match(/product[_/]?id[=/](\d+)/i) ||
116	                    String(row.href || '').match(/\/product\/(\d+)/) ||
117	                    String(txt).match(/\b(\d{6,})\b/);
118	                  if (pm) row.productId = pm[1];
119	                }
120	              } else if (f === 'title' && !row.productId) {
121	                var idm = String(txt).match(/\b(\d{6,})\b/);
122	                if (idm) row.productId = idm[1];
123	              }
124	            }
125	          } else {
126	            row[f] = parseNumber(txt);
127	          }
128	        }
129	        if (
130	          row.productId ||
131	          row.title ||
132	          row.impressions != null ||
133	          row.clicks != null ||
134	          row.ctr != null ||
135	          row.gmv != null
136	        ) {
137	          items.push(row);
138	        }
139	      }
140	      if (items.length > best.length) {
141	        best = items;
142	        bestHeaders = headers;
143	      }
144	    }
145	    return { products: best, headers: bestHeaders };
146	  }
147	  try {
148	    var body = bodyText();
149	    var url = location.href || '';
150	    var title = document.title || '';
151	    var windowLabel = null;
152	    var wm =
153	      body.match(/近\s*\d+\s*天/) ||
154	      body.match(/Last\s*\d+\s*days?/i) ||
155	      body.match(/\d{4}[\/\-]\d{1,2}[\/\-]\d{1,2}\s*[\-~至]\s*\d{4}[\/\-]\d{1,2}[\/\-]\d{1,2}/) ||
156	      body.match(/Yesterday|昨天|Today|今天/i);
157	    if (wm) windowLabel = wm[0];
158	
159	    var kpis = {
160	      impressions: findByRegex(body, [
161	        /曝光用户数\s*([\d,.]+[KkMm万亿]?)/i,
162	        /商品\s*曝光\s*([£$€]?[\d,.]+[KkMm万亿]?)/i,
163	        /曝光数?\s*([\d,.]+[KkMm万亿]?)/,
164	        /Impressions?\s*([\d,.]+[KkMm万亿]?)/i
165	      ]),
166	      clicks: findByRegex(body, [
167	        /点击数?\s*([\d,.]+[KkMm万亿]?)/,
168	        /Clicks?\s*([\d,.]+[KkMm万亿]?)/i
169	      ]),
170	      ctr: findByRegex(body, [/点击率\s*([\d.]+)\s*%?/, /\bCTR\s*([\d.]+)\s*%?/i]),
171	      orders: findByRegex(body, [
172	        /SKU\s*订单数?\s*([\d,.]+)/i,
173	        /订单数?\s*([\d,.]+)/,
174	        /Orders?\s*([\d,.]+)/i
175	      ]),
176	      gmv: findByRegex(body, [
177	        /GMV\s*([£$€]?[\d,]+\.?\d*)/i,
178	        /成交额\s*([£$€]?[\d,]+\.?\d*)/,
179	        /销售额\s*([£$€]?[\d,]+\.?\d*)/
180	      ]),
181	      cvr: findByRegex(body, [
182	        /曝光到成交转化率\s*([\d.]+)\s*%?/,
183	        /转化率\s*([\d.]+)\s*%?/,
184	        /\bCVR\s*([\d.]+)\s*%?/i
185	      ]),
186	      customers: findByRegex(body, [/日客户数\s*([\d,.]+)/, /客户数\s*([\d,.]+)/i])
187	    };
188	
189	    var tbl = scrapeProductTable();
190	    var kpiFlat = {};
191	    var kpiHits = {};
192	    Object.keys(kpis).forEach(function (k) {
193	      if (kpis[k]) {
194	        kpiFlat[k] = kpis[k].value;
195	        kpiHits[k] = kpis[k].label;
196	      } else {
197	        kpiFlat[k] = null;
198	      }
199	    });
200	
201	    var pageHints = {
202	      hasProductCardNav: /商品卡|Product\s*card|商品数据|Product\s*analytics|商品分析/i.test(body),
203	      hasTrafficWord: /曝光|点击|CTR|CVR|Impression/i.test(body)
204	    };
205	
206	    var hasKpi = Object.keys(kpiFlat).some(function (k) {
207	      return kpiFlat[k] != null;
208	    });
209	    var hasRows = tbl.products && tbl.products.length > 0;
210	    var ok = !!(hasKpi || hasRows);
211	
212	    var raw = {
213	      bodyLen: body.length,
214	      sample: body.slice(0, 500),
215	      window: windowLabel,
216	      kpiHits: kpiHits,
217	      tableHeaders: tbl.headers,
218	      productRowCount: tbl.products.length,
219	      pageHints: pageHints
220	    };
221	
222	    if (!ok) {
223	      return JSON.stringify({
224	        ok: false,
225	        module: 'product_traffic',
226	        source: 'product-traffic-poc',
227	        url: url,
228	        title: title,
229	        window: windowLabel,
230	        currency: detectCurrency(body),
231	        kpis: kpiFlat,
232	        products: [],
233	        raw: raw,
234	        error:
235	          'no product traffic KPI or rows. Confirm URL is 内容分析→商品卡/商品数据. url=' + url
236	      });
237	    }
238	
239	    return JSON.stringify({
240	      ok: true,
241	      module: 'product_traffic',
242	      source: 'product-traffic-poc',
243	      url: url,
244	      title: title,
245	      window: windowLabel,
246	      currency: detectCurrency(body) || 'GBP',
247	      channelDefault: 'product_card',
248	      kpis: kpiFlat,
249	      products: tbl.products,
250	      raw: raw,
251	      error: null
252	    });
253	  } catch (e) {
254	    return JSON.stringify({
255	      ok: false,
256	      module: 'product_traffic',
257	      url: location.href || '',
258	      error: String(e && e.message ? e.message : e)
259	    });
260	  }
261	})();
