1	/* Click Compass top-nav by visible label. Ziniao page exec.
2	 * Return { ok, action, beforeUrl, afterUrl, matchedText, error }
3	 * Usage: set window.__QQ_CLICK_NAV_LABEL__ = '内容分析' before exec, or edit DEFAULT_LABEL.
4	 */
5	(function () {
6	  var DEFAULT_LABEL = '内容分析';
7	  function clean(t) {
8	    return String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
9	  }
10	  function label() {
11	    try {
12	      if (typeof window.__QQ_CLICK_NAV_LABEL__ === 'string' && window.__QQ_CLICK_NAV_LABEL__) {
13	        return String(window.__QQ_CLICK_NAV_LABEL__);
14	      }
15	    } catch (e) {}
16	    return DEFAULT_LABEL;
17	  }
18	  function clickEl(el) {
19	    if (!el) return false;
20	    try {
21	      el.scrollIntoView({ block: 'center', inline: 'center' });
