127	function Test-BridgeAlive {
128	  try {
129	    $null = Invoke-WebRequest -Uri 'http://127.0.0.1:9481' -TimeoutSec 3 -UseBasicParsing -ErrorAction Stop
130	    return $true
131	  } catch {
132	    # Bridge often returns 401 without auth — still means process is up
133	    $msg = [string]$_.Exception.Message
134	    if ($msg -match '401|403|Unauthorized|Forbidden') { return $true }
135	    return $false
136	  }
137	}
