139	function Invoke-EnsurePageReady {
140	  param(
141	    [string]$StoreId,
142	    [string]$TargetUrl,
143	    [string]$UrlCheckOneLiner,
144	    [int]$MaxTries = 3
145	  )
146	  for ($t = 1; $t -le $MaxTries; $t++) {
147	    if (-not (Test-BridgeAlive)) {
148	      Write-Step ("  bridge down try {0}/{1}, wait 15s..." -f $t, $MaxTries)
149	      Start-Sleep -Seconds 15
150	      if (-not (Test-BridgeAlive)) {
151	        if ($t -eq $MaxTries) { return @{ ok = $false; error = 'bridge unreachable' } }
152	        continue
153	      }
154	    }
155	    try {
156	      $null = Invoke-Ziniao @('page', 'visit', '--store-id', $StoreId, '--url', $TargetUrl, '--wait-until', 'load', '--timeout', '120000')
157	    } catch {
158	      Write-Step ("  visit error try {0}: {1}" -f $t, $_)
159	      Start-Sleep -Seconds 8
160	      continue
161	    }
162	    Start-Sleep -Seconds 8
163	    $chkOut = ''
164	    try {
165	      $chkOut = Invoke-Ziniao @('page', 'exec', '--store-id', $StoreId, '--script', $UrlCheckOneLiner, '--timeout', '30000')
166	    } catch {
167	      Write-Step ("  url-check exec fail try {0}: {1}" -f $t, $_)
168	      Start-Sleep -Seconds 10
169	      continue
170	    }
171	    $chk = Get-ScrapePayload $chkOut
172	    $href = ''
173	    if ($chk -and $chk.href) { $href = [string]$chk.href }
174	    $blank = $false
175	    if ($chk -and $chk.blank) { $blank = [bool]$chk.blank }
176	    if (-not $href -or $href -match 'about:blank' -or $blank) {
177	      Write-Step ("  page not ready try {0}/{1}: href={2}" -f $t, $MaxTries, $href)
178	      Start-Sleep -Seconds 12
179	      continue
180	    }
181	    # Wrong landing: content-analysis/* or video-analytics/overview often bounce to data-overview
182	    if ($href -match 'data-overview' -and $TargetUrl -notmatch 'data-overview') {
183	      Write-Step ("  landed data-overview (want {0}), retry visit..." -f $TargetUrl)
184	      Start-Sleep -Seconds 5
185	      continue
186	    }
187	    return @{ ok = $true; href = $href; bodyLen = $(if ($chk.bodyLen) { $chk.bodyLen } else { 0 }) }
188	  }
189	  return @{ ok = $false; error = 'page not ready after retries' }
190	}
191	
192	function Get-ModuleUrl($store, $cfg, $moduleKey) {
193	  $plat = ''
194	  if ($store.platformName) { $plat = [string]$store.platformName }
195	  elseif ($store.platform) { $plat = [string]$store.platform }
196	  $mapKey = switch ($moduleKey) {
197	    'content_overview' { 'contentUrl' }
198	    'product_traffic' { 'productTrafficUrl' }
199	    'video_list' { 'videoListUrl' }
200	    'content_probe' { 'contentUrl' }
201	    'content_nav_discover' { 'contentNavStartUrl' }
202	    default { $null }
203	  }
204	  # 2026-08-04 实勘默认（Deal UK）；content-analysis/* 会回 data-overview
205	  # video_list: 视频详情候选 path（P2.1b）；以实跑矩阵为准
206	  $defaults = @{
