  }
  function matchVideoHeader(h) {
    var t = clean(h).toLowerCase();
    if (!t) return null;
    if (/视频\s*id|video\s*id|content\s*id|\bid\b/.test(t) && !/商品|product/.test(t)) return 'contentId';
    if (/视频|video|内容|content|作品|title|名称|name/.test(t) && !/gmv|订单|曝光|播放|点击|转化/.test(t))
      return 'title';
