      if ($chk2 -and $chk2.href) { $href = [string]$chk2.href }
      if ($bodyLen -lt 800 -and $t -lt $MaxTries) { continue }
    }
    return @{ ok = $true; href = $href; bodyLen = $bodyLen }
  }
  return @{ ok = $false; error = 'page not ready after retries' }
}

