input.command:
# UTF8 read config
$cfgPath = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\config\stores.config.deal-only.json"
$cfg = Get-Content $cfgPath -Raw -Encoding UTF8 | ConvertFrom-Json
Write-Host "baseUrl=$($cfg.qingquan.baseUrl) videoList=$($cfg.videoListUrl.default)"
# openapi paths
$oa = Invoke-RestMethod -Uri "https://qingquan.jmzlai.com/openapi.json" -TimeoutSec 30
$oa.paths.PSObject.Properties.Name | Where-Object { $_ -match 'product|ingest|tk/' } | Sort-Object
# minimal ingest
$item = @{
  platform="tiktok"; shop_id="27501502216807"; shop_name="Deal"; biz_date="2026-08-04"
  collected_at="2026-08-05T01:00:00+00:00"
  idempotency_key="tiktok_product_traffic:test:20260805:probe2"
  payload=@{ product_id="1729865746588211715"; channel="product_card"; gmv=1.0; impressions=10; currency="GBP"; window="最近 7 天" }
}
$body = @{ items = @($item) } | ConvertTo-Json -Depth 8 -Compress
$bytes = [System.Text.Encoding]::UTF8.GetBytes($body)
try {
  $r = Invoke-WebRequest -Uri "$($cfg.qingquan.baseUrl)/api/v1/ingest/tiktok_product_traffic" -Method POST -Headers @{ "X-API-Key"=$cfg.qingquan.apiKey; "Content-Type"="application/json; charset=utf-8" } -Body $bytes -TimeoutSec 60 -UseBasicParsing
  Write-Host "OK $($r.StatusCode) $($r.Content)"
} catch {
  Write-Host $_.Exception.Message
  $resp = $_.Exception.Response
  if ($resp) {
    Write-Host "StatusCode:" ([int]$resp.StatusCode)
    $stream = $resp.GetResponseStream()
    $reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8)
    Write-Host ("BODY: " + $reader.ReadToEnd())
  }
}

