# Shared Ziniao store-window helpers: --window-ratio + Win32 maximize + page resize.
# Dot-source from run-*.ps1 after open / visit so Compass tables get full viewport.
#
#   . (Join-Path $PSScriptRoot 'ziniao-window.ps1')
#   $openArgs = New-ZiniaoStoreOpenArgs -StoreId $sid -Url $url -Config $cfg
#   Invoke-Ziniao $openArgs
#   Invoke-ZiniaoStoreMaximize -StoreId $sid -InvokeZiniao ${function:Invoke-Ziniao} -WriteStep ${function:Write-Step}

function Get-ZiniaoWindowRatio($cfg) {
  $ratio = 'full'
  if ($cfg -and $cfg.options -and $cfg.options.PSObject.Properties.Name -contains 'windowRatio' -and $cfg.options.windowRatio) {
    $ratio = [string]$cfg.options.windowRatio
  }
  return $ratio
}

function Test-ZiniaoMaximizeEnabled($cfg) {
  # default ON; set options.maximizeWindow=false to disable
  if ($cfg -and $cfg.options -and $null -ne $cfg.options.maximizeWindow) {
    return [bool]$cfg.options.maximizeWindow
  }
  return $true
}

function New-ZiniaoStoreOpenArgs {
  param(
    [Parameter(Mandatory = $true)][string]$StoreId,
    [Parameter(Mandatory = $true)][string]$Url,
    $Config = $null,
    [string]$WindowRatio = ''
  )
  $argsList = [System.Collections.Generic.List[string]]::new()
  $argsList.AddRange([string[]]@('store', 'open', '--id', $StoreId, '--url', $Url))
  $ratio = $WindowRatio
  if (-not $ratio) { $ratio = Get-ZiniaoWindowRatio $Config }
  if ($ratio -and $ratio -ne 'default' -and $ratio -ne 'none') {
    $argsList.Add('--window-ratio')
    $argsList.Add($ratio)
  }
  return @($argsList.ToArray())
}

function Maximize-ZiniaoBrowserWindows {
  # 紫鸟开店默认常是小窗；Win32 SW_MAXIMIZE 比单靠 --window-ratio 稳
  $code = @'
using System;
using System.Text;
using System.Diagnostics;
using System.Runtime.InteropServices;

public class ZiniaoWinMax {
  public delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hWnd);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
  const int SW_RESTORE = 9;
  const int SW_MAXIMIZE = 3;

  static string ProcName(IntPtr hWnd) {
    try {
      uint pid;
      GetWindowThreadProcessId(hWnd, out pid);
      if (pid == 0) return "";
      var p = Process.GetProcessById((int)pid);
      return p != null ? (p.ProcessName ?? "") : "";
    } catch { return ""; }
  }

  public static int MaximizeMatching() {
    int n = 0;
    EnumWindows((hWnd, l) => {
      if (!IsWindowVisible(hWnd)) return true;
      var title = new StringBuilder(512);
      var cls = new StringBuilder(256);
      GetWindowText(hWnd, title, title.Capacity);
      GetClassName(hWnd, cls, cls.Capacity);
      string t = title.ToString();
      string c = cls.ToString();
      string pn = ProcName(hWnd);

      if (t.IndexOf("DevTools", StringComparison.OrdinalIgnoreCase) >= 0) return true;

      bool chromeClass = c.IndexOf("Chrome_WidgetWin", StringComparison.OrdinalIgnoreCase) >= 0;
      bool ziniaoProc =
           pn.IndexOf("ziniao", StringComparison.OrdinalIgnoreCase) >= 0
        || pn.IndexOf("紫鸟", StringComparison.OrdinalIgnoreCase) >= 0
        || pn.IndexOf("SuperBrowser", StringComparison.OrdinalIgnoreCase) >= 0
        || pn.IndexOf("bitbrowser", StringComparison.OrdinalIgnoreCase) >= 0
        || pn.IndexOf("chrome", StringComparison.OrdinalIgnoreCase) >= 0; // 紫鸟内核常挂 chrome.exe

      bool titleHint =
           t.IndexOf("TikTok", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("tiktok", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("seller", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("Shop", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("紫鸟", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("Ziniao", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("ads-creation", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("商家中心", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("Seller Center", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("compass", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("Tiktok_Shop", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("Gardena", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("Deal", StringComparison.OrdinalIgnoreCase) >= 0
        || t.IndexOf("Nookora", StringComparison.OrdinalIgnoreCase) >= 0;

      // 排除系统/普通 Google Chrome 主页（进程名 chrome 且标题带 Google Chrome）
      bool plainGoogleChrome =
           pn.Equals("chrome", StringComparison.OrdinalIgnoreCase)
        && (t.IndexOf(" - Google Chrome", StringComparison.OrdinalIgnoreCase) >= 0
            || t.IndexOf("新标签页", StringComparison.OrdinalIgnoreCase) >= 0
            || t.IndexOf("New Tab", StringComparison.OrdinalIgnoreCase) >= 0);

      if (plainGoogleChrome) return true;

      // 命中：标题像店铺/卖家中心，或（Chromium 类 + 非空标题且非明显无关）
      bool hit = false;
      if (titleHint && (chromeClass || ziniaoProc || t.Length > 0)) hit = true;
      else if (chromeClass && t.Length >= 2 && !plainGoogleChrome) {
        // 开店后常见：标题=店铺配置名 / 仅 Seller Center，无 TikTok 字样
        hit = true;
      }

      if (hit) {
        if (IsIconic(hWnd)) ShowWindow(hWnd, SW_RESTORE);
        ShowWindow(hWnd, SW_MAXIMIZE);
        try { SetForegroundWindow(hWnd); } catch { }
        n++;
      }
      return true;
    }, IntPtr.Zero);
    return n;
  }
}
