92	        || pn.IndexOf("SuperBrowser", StringComparison.OrdinalIgnoreCase) >= 0
93	        || pn.IndexOf("bitbrowser", StringComparison.OrdinalIgnoreCase) >= 0
94	        || pn.IndexOf("ziniaobrowser", StringComparison.OrdinalIgnoreCase) >= 0;
95	
96	      bool titleHint =
97	           t.IndexOf("TikTok", StringComparison.OrdinalIgnoreCase) >= 0
98	        || t.IndexOf("tiktok", StringComparison.OrdinalIgnoreCase) >= 0
99	        || t.IndexOf("seller", StringComparison.OrdinalIgnoreCase) >= 0
100	        || t.IndexOf("Shop", StringComparison.OrdinalIgnoreCase) >= 0
101	        || t.IndexOf("紫鸟", StringComparison.OrdinalIgnoreCase) >= 0
102	        || t.IndexOf("Ziniao", StringComparison.OrdinalIgnoreCase) >= 0
103	        || t.IndexOf("ads-creation", StringComparison.OrdinalIgnoreCase) >= 0
104	        || t.IndexOf("商家中心", StringComparison.OrdinalIgnoreCase) >= 0
105	        || t.IndexOf("Seller Center", StringComparison.OrdinalIgnoreCase) >= 0
106	        || t.IndexOf("compass", StringComparison.OrdinalIgnoreCase) >= 0
107	        || t.IndexOf("Tiktok_Shop", StringComparison.OrdinalIgnoreCase) >= 0
108	        || t.IndexOf("Gardena", StringComparison.OrdinalIgnoreCase) >= 0
109	        || t.IndexOf("Deal to deal", StringComparison.OrdinalIgnoreCase) >= 0
110	        || t.IndexOf("Nookora", StringComparison.OrdinalIgnoreCase) >= 0
111	        || t.IndexOf("KK Seagull", StringComparison.OrdinalIgnoreCase) >= 0;
112	
113	      // 普通 Google Chrome 主页/标签：跳过
114	      bool plainGoogleChrome =
115	           pn.Equals("chrome", StringComparison.OrdinalIgnoreCase)
116	        && !titleHint
117	        && (t.IndexOf(" - Google Chrome", StringComparison.OrdinalIgnoreCase) >= 0
118	            || t.IndexOf("新标签页", StringComparison.OrdinalIgnoreCase) >= 0
119	            || t.IndexOf("New Tab", StringComparison.OrdinalIgnoreCase) >= 0
120	            || t.Length == 0);
121	
122	      if (plainGoogleChrome) return true;
123	
