156	    'return JSON.stringify({ok:true,w:window.outerWidth||0,h:window.outerHeight||0,sw:screen.availWidth||0,sh:screen.availHeight||0});'
157	    '}catch(e){return JSON.stringify({ok:false,error:String(e&&e.message||e)});}})();'
158	  ) -join ''
159	}
