162	  param(
163	    [string]$StoreId = '',
164	    [scriptblock]$InvokeZiniao = $null,
165	    [scriptblock]$WriteStep = $null,
166	    $Config = $null,
167	    [switch]$SkipPageExec,
168	    [int]$PageExecTimeoutMs = 15000
169	  )
170	  if (-not (Test-ZiniaoMaximizeEnabled $Config)) {
171	    if ($WriteStep) { & $WriteStep '  maximize skipped (options.maximizeWindow=false)' }
172	    return @{ win32 = 0; page = $null; skipped = $true }
173	  }
174	
175	  $n = 0
176	  try {
177	    $n = Maximize-ZiniaoBrowserWindows
178	    if ($WriteStep) { & $WriteStep ("  maximize Win32 hit={0}" -f $n) }
179	  } catch {
180	    if ($WriteStep) { & $WriteStep ("  WARN maximize Win32: {0}" -f $_) }
181	  }
182	
183	  $pagePayload = $null
184	  if (-not $SkipPageExec -and $StoreId -and $InvokeZiniao) {
185	    try {
186	      $maxJs = Get-ZiniaoPageMaximizeScript
187	      $out = & $InvokeZiniao @('page', 'exec', '--store-id', $StoreId, '--script', $maxJs, '--timeout', ([string]$PageExecTimeoutMs))
188	      if ($WriteStep -and $out) {
189	        $one = ([string]$out) -replace '\s+', ' '
190	        if ($one.Length -gt 220) { $one = $one.Substring(0, 220) + '...' }
191	        & $WriteStep ("  maximize page: {0}" -f $one)
192	      }
193	      $pagePayload = $out
194	    } catch {
195	      if ($WriteStep) { & $WriteStep ("  WARN maximize page exec: {0}" -f $_) }
196	    }
197	  }
198	
199	  return @{ win32 = $n; page = $pagePayload; skipped = $false }
200	}
