      if ($WriteStep -and $out) {
        $one = ([string]$out) -replace '\s+', ' '
        if ($one.Length -gt 220) { $one = $one.Substring(0, 220) + '...' }
        & $WriteStep ("  maximize page: {0}" -f $one)
      }
      $pagePayload = $out
    } catch {
      if ($WriteStep) { & $WriteStep ("  WARN maximize page exec: {0}" -f $_) }
