    var href = pickBestHref(el) || '';
    var id = extractVideoIdFromHref(href);
    if (!id || seen[id]) continue;
    if (!/视频|video|播放|gmv|曝光|转化|vv/i.test(txt) && !/video-detail/i.test(href)) continue;
    seen[id] = true;
    hits.push({
      contentId: id,
      title: txt.slice(0, 160),
      href: href || null,
      source: 'div_list'
    });
  }
  return hits;
}
