  Write-Host "缺少环境变量。需要："
  Write-Host '  FEISHU_APP_ID / FEISHU_APP_SECRET / FEISHU_APP_TOKEN(或 BITABLE APP TOKEN TK)'
  Write-Host '  以及至少一张：FEISHU_TABLE_TK_SHOP_DAILY / FEISHU_TABLE_TK_ADS_CAMPAIGN'
