}
$token = $tokenResp.tenant_access_token
$auth = @{ Authorization = "Bearer $token" }
Write-Host "   OK  app_token=$appToken"

function Ensure-Fields {
  param($Label, $TableId, $FieldSpecs)
  Write-Host ""
  Write-Host "=== $Label  table=$TableId ==="
  $listUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$appToken/tables/$TableId/fields?page_size=100"
  $listResp = Invoke-FeishuJson -Method GET -Url $listUrl -Headers $auth -Body $null
  if ($listResp.code -ne 0) {
    throw "列字段失败 ($Label): code=$($listResp.code) msg=$($listResp.msg)"
  }
  $existing = @{}
  foreach ($f in @($listResp.data.items)) {
    if ($f.field_name) { $existing[$f.field_name] = $f }
  }
  Write-Host ("   已有 {0} 字段" -f $existing.Count)

  $createUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$appToken/tables/$TableId/fields"
  $created = 0; $skipped = 0; $failed = @()
  foreach ($spec in $FieldSpecs) {
    $name = $spec.field_name
    if ($existing.ContainsKey($name)) {
      Write-Host "   skip  $name"
      $skipped++
      continue
    }
    try {
      $r = Invoke-FeishuJson -Method POST -Url $createUrl -Headers $auth -Body $spec
      if ($r.code -eq 0) {
        Write-Host "   OK    $name"
        $created++
      }
      else {
        Write-Host "   FAIL  $name code=$($r.code) msg=$($r.msg)"
        $failed += "$name : $($r.msg)"
      }
    }
    catch {
      Write-Host "   ERR   $name $_"
      $failed += "$name : $_"
    }
    Start-Sleep -Milliseconds 250
  }
  Write-Host "   小结: 新建 $created , 跳过 $skipped , 失败 $($failed.Count)"
  if ($failed.Count -gt 0) {
    $failed | ForEach-Object { Write-Host "     - $_" }
  }
}

foreach ($t in $targets) {
  Ensure-Fields -Label $t.name -TableId $t.tableId -FieldSpecs $t.fields

# TK P0: after collectors finish — anomaly rules + Feishu T1/T2/anomaly sync.
# Rules order: ads → product → shop(①店铺分析) → feishu.
# Safe to re-run (rules upsert open tasks; feishu sync is idempotent via map).
#
# Usage (repo root):
#   powershell -ExecutionPolicy Bypass -File .\scripts\tk-p0-post-collect.ps1
#   powershell -ExecutionPolicy Bypass -File .\scripts\tk-p0-post-collect.ps1 -LookbackDays 7
#   powershell -ExecutionPolicy Bypass -File .\scripts\tk-p0-post-collect.ps1 -SkipRules
#   powershell -ExecutionPolicy Bypass -File .\scripts\tk-p0-post-collect.ps1 -SkipFeishu -DryRun

param(
  [int]$LookbackDays = 14,
  [switch]$SkipRules,
  [switch]$SkipFeishu,
  [switch]$DryRun,
  [string]$BizDate = ""
)

$ErrorActionPreference = 'Continue'
$RepoRoot = Split-Path $PSScriptRoot -Parent
if (-not (Test-Path (Join-Path $RepoRoot 'backend\app'))) {
  # script may live at repo/scripts; cwd-aware fallback
  if (Test-Path (Join-Path $PSScriptRoot '..\backend\app')) {
    $RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
  }
}

$logDir = Join-Path $RepoRoot 'logs'
New-Item -ItemType Directory -Force -Path $logDir | Out-Null
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$logFile = Join-Path $logDir "tk-p0-post-collect-$stamp.log"

function Log([string]$msg) {
  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
  Add-Content -Path $logFile -Value $line -Encoding UTF8
  Write-Host $line
}

function Find-Python() {
  $cands = @(
    (Join-Path $RepoRoot 'backend\.venv\Scripts\python.exe'),
    (Join-Path $RepoRoot '.venv\Scripts\python.exe'),
    'python'
  )
  foreach ($c in $cands) {
    if ($c -eq 'python') { return $c }
    if (Test-Path $c) { return $c }
  }
  return 'python'
}

Log "===== TK P0 post-collect START ====="
Log "root=$RepoRoot log=$logFile lookback=$LookbackDays dryRun=$DryRun"

$py = Find-Python
Log "python=$py"
$backend = Join-Path $RepoRoot 'backend'
$env:PYTHONPATH = $backend
if (Test-Path (Join-Path $RepoRoot '.env')) {
  # jobs read Settings from cwd/env; prefer backend cwd
  Log "note: ensure FEISHU_* / DATABASE_URL loaded via backend Settings (.env)"
}

$codes = @()

if (-not $SkipRules) {
  Push-Location $backend
  try {
    $adsJob = Join-Path $backend 'app\jobs\tk_ads_anomaly_eval.py'
    $prodJob = Join-Path $backend 'app\jobs\tk_product_anomaly_eval.py'
    $shopJob = Join-Path $backend 'app\jobs\tk_shop_anomaly_eval.py'
    $contentJob = Join-Path $backend 'app\jobs\tk_content_anomaly_eval.py'
    if (Test-Path $adsJob) {
      $argsAds = @('-m', 'app.jobs.tk_ads_anomaly_eval')
      if ($DryRun) { $argsAds += '--dry-run' }
      if ($BizDate) { $argsAds += @('--biz-date', $BizDate) }
      Log ("run ads anomaly: {0}" -f ($argsAds -join ' '))
      & $py @argsAds
      $codes += $LASTEXITCODE
      Log ("ads anomaly exit={0}" -f $LASTEXITCODE)
    } else {
      Log "WARN missing $adsJob — skip ads rules CLI"
    }
    if (Test-Path $prodJob) {
      $argsP = @('-m', 'app.jobs.tk_product_anomaly_eval')
      if ($DryRun) { $argsP += '--dry-run' }
      Log ("run product anomaly: {0}" -f ($argsP -join ' '))
      & $py @argsP
      $codes += $LASTEXITCODE
      Log ("product anomaly exit={0}" -f $LASTEXITCODE)
    } else {
      Log "WARN missing $prodJob — skip product rules CLI"
    }
    if (Test-Path $shopJob) {
      $argsS = @('-m', 'app.jobs.tk_shop_anomaly_eval')
      if ($DryRun) { $argsS += '--dry-run' }
      if ($BizDate) { $argsS += @('--biz-date', $BizDate) }
      Log ("run shop anomaly: {0}" -f ($argsS -join ' '))
      & $py @argsS
      $codes += $LASTEXITCODE
      Log ("shop anomaly exit={0}" -f $LASTEXITCODE)
    } else {
      Log "WARN missing $shopJob — skip shop rules CLI"
    }
    if (Test-Path $contentJob) {
      $argsC = @('-m', 'app.jobs.tk_content_anomaly_eval')
      if ($DryRun) { $argsC += '--dry-run' }
      if ($BizDate) { $argsC += @('--biz-date', $BizDate) }
      Log ("run content anomaly: {0}" -f ($argsC -join ' '))
      & $py @argsC
      $codes += $LASTEXITCODE
      Log ("content anomaly exit={0}" -f $LASTEXITCODE)
    } else {
      Log "WARN missing $contentJob — skip content rules CLI"
    }
  } finally {
    Pop-Location
  }
} else {
  Log "SkipRules"
}

if (-not $SkipFeishu) {
  $syncPy = Join-Path $RepoRoot 'scripts\feishu_tk_daily_sync.py'
  if (-not (Test-Path $syncPy)) {
    Log "FATAL missing $syncPy"
    $codes += 1
  } else {
    $argsS = @($syncPy, '--lookback-days', "$LookbackDays")
    if ($DryRun) { $argsS += '--dry-run' }
    Log ("run feishu sync: {0}" -f ($argsS -join ' '))
    & $py @argsS
    $codes += $LASTEXITCODE
    Log ("feishu sync exit={0}" -f $LASTEXITCODE)
  }
} else {
  Log "SkipFeishu"
}

$failed = @($codes | Where-Object { $_ -ne 0 -and $_ -ne $null }).Count
$final = if ($failed -gt 0) { 1 } else { 0 }
Log ("steps={0} failed={1} final={2}" -f $codes.Count, $failed, $final)
Log "===== TK P0 post-collect END ====="
exit $final

# -*- coding: utf-8 -*-
"""为 TK 驾驶舱 T1/T2 创建推荐网格视图（筛选需在飞书 UI 按说明补）。"""
from __future__ import annotations

import json
import time
import urllib.error
import urllib.request
from pathlib import Path

# 读仓库根 .env（不打印 secret）
ROOT = Path(__file__).resolve().parents[1]
env: dict[str, str] = {}
for line in (ROOT / ".env").read_text(encoding="utf-8").splitlines():
    line = line.strip()
    if not line or line.startswith("#") or "=" not in line:
        continue
    k, v = line.split("=", 1)
    env[k.strip()] = v.strip().strip('"').strip("'")

APP_ID = env.get("FEISHU_APP_ID") or ""
APP_SECRET = env.get("FEISHU_APP_SECRET") or ""
APP_TOKEN = (
    env.get("FEISHU_BITABLE_APP_TOKEN_TK")
    or env.get("FEISHU_BITABLE_APP_TOKEN")
    or ""
)
T1 = env.get("FEISHU_BITABLE_TABLE_TK_SHOP_DAILY") or ""
T2 = env.get("FEISHU_BITABLE_TABLE_TK_ADS_CAMPAIGN") or ""

VIEWS = {
    "T1店铺日经营": (
        T1,
        ["昨日全店", "近7日明细", "低ROI店", "健康预警"],
    ),
    "T2广告活动日明细": (
        T2,
        ["昨日花费Top", "低效亏损", "高ROI", "预算将尽"],
    ),
}


def req(method: str, url: str, body=None, token: str | None = None) -> dict:
    data = None
    headers = {"Content-Type": "application/json; charset=utf-8"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    if body is not None:
        data = json.dumps(body, ensure_ascii=False).encode("utf-8")
    r = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(r, timeout=60) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", errors="replace")
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return {"code": e.code, "msg": raw}


def main() -> int:
    if not all([APP_ID, APP_SECRET, APP_TOKEN, T1, T2]):
        print("missing FEISHU_* in .env")
        return 1
    tok = req(
        "POST",
        "https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal",
        {"app_id": APP_ID, "app_secret": APP_SECRET},
    )
    if tok.get("code") != 0:
        print("token fail", tok)
        return 1
    token = tok["tenant_access_token"]
    print("token ok")

    for label, (tid, names) in VIEWS.items():
        print(f"\n=== {label} {tid} ===")
        listed = req(
            "GET",
            f"https://open.feishu.cn/open-apis/bitable/v1/apps/{APP_TOKEN}/tables/{tid}/views",
            token=token,
        )
        if listed.get("code") != 0:
            print("  list views fail", listed)
            continue
        existing = {
            (v.get("view_name") or "")
            for v in (listed.get("data") or {}).get("items") or []
        }
        print("  existing:", sorted(existing) or "(none)")
        for name in names:
            if name in existing:
                print(f"  skip {name}")
                continue
            r = req(
                "POST",
                f"https://open.feishu.cn/open-apis/bitable/v1/apps/{APP_TOKEN}/tables/{tid}/views",
                {"view_name": name, "view_type": "grid"},
                token,
            )
            if r.get("code") == 0:
                vid = (r.get("data") or {}).get("view_id") or (
                    (r.get("data") or {}).get("view") or {}
                ).get("view_id")
                print(f"  OK   {name}  view_id={vid}")
                existing.add(name)
            else:
                print(f"  FAIL {name} {r.get('code')} {r.get('msg')}")
            time.sleep(0.3)
    print("\nDONE — 筛选/排序请在飞书 UI 按 docs/TK-飞书驾驶舱仪表盘搭法.md 补")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

