            f"https://open.feishu.cn/open-apis/bitable/v1/apps/{app_token}/tables/{tid}/fields/{f['field_id']}",
            body,
            token,
        )
        if r.get("code") == 0:
            print(f"UPDATED {fname} +{missing}")
        else:
            print(f"FAIL update {fname}", r)
            return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
